(window.KOTOBA_HK=window.KOTOBA_HK||{})[5]={"n":5,"S":[{"id":"l05a","ti":[[["おむすび","おむすび"],["ころりん","ころりん"]]],"tt":{"az":"Diyirlənən düyü topası","en":"The Rolling Rice Ball","ru":"Катящийся рисовый шарик"},"P":[{"t":[[["むかし","むかし"],["、"],["ある","ある","ある(連体詞)"]],[["村","むら"],["に","に"],["、"],["おじいさん","おじいさん"],["と","と"]],[["おばあさん","おばあさん"],["が","が"]],[["いました","いました","いる",2],["。"],["ある","ある","ある(連体詞)"]],[["朝","あさ"],["、"],["おじいさん","おじいさん"],["は","は"]],[["一人","ひとり"],["で","で"]],[["山","やま"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["山","やま"],["まで","まで"]],[["歩いて","あるいて","歩く",3]],[["一時間","いちじかん"],["でした","でした","です",9],["。"],["おばあさん","おばあさん"],["の","の"]],[["おむすび","おむすび"],["が","が"]],[["今日","きょう"],["の","の"]],[["お昼ご飯","おひるごはん"],["でした","でした","です",9],["。"]]],"tr":{"az":"Qədim zamanlarda bir kənddə bir baba ilə bir nənə yaşayırdı. Bir səhər baba dağa tək getdi. Dağa piyada bir saatlıq yol idi. Həmin gün nahara nənənin hazırladığı düyü topalarını yeyəcəkdi.","en":"Long ago, an old man and an old woman lived in a village. One morning, the old man went to the mountain alone. It was an hour away on foot. The old woman's rice balls were his lunch that day.","ru":"Давным-давно в одной деревне жили дедушка и бабушка. Однажды утром дедушка один отправился в горы. Пешком туда было час пути. На обед у него были рисовые шарики, которые приготовила бабушка."}},{"t":[[["昼","ひる"],["、"],["おじいさん","おじいさん"],["は","は"]],[["木","き"],["の","の"]],[["下","した"],["で","で","だ"]],[["おむすび","おむすび"],["を","を"]],[["食べました","たべました","食べる",2],["。"],["一つ","ひとつ"],["の","の"]],[["おむすび","おむすび"],["が","が"]],[["ころころ","ころころ"]],[["転がって","ころがって","転がる",3],["、"],["小さい","ちいさい"]],[["穴","あな"],["に","に"]],[["落ちました","おちました","落ちる",2],["。"],["穴","あな"],["の","の"]],[["中","なか"],["から","から"],["「"],["おむすび","おむすび"],["ころりん","ころりん"],["、"],["すっとんとん","すっとんとん"],["」"],["と","と"]],[["楽しい","たのしい"]],[["歌","うた"],["が","が"]],[["聞こえました","きこえました","聞こえる",2],["。"]]],"tr":{"az":"Günorta baba ağacın altında düyü topalarını yedi. Onlardan biri diyirlənib balaca bir dəliyə düşdü. Dəliyin içindən şən bir mahnı eşidildi: «Düyü topası diyirləndi, hoppadan düşdü!»","en":"At noon, the old man ate his rice balls under a tree. One rice ball rolled away and fell into a little hole. From inside came a cheerful song: \"Roll, rice ball, roll! Plop into the hole!\"","ru":"В полдень дедушка ел рисовые шарики под деревом. Один шарик покатился и упал в маленькую норку. Из норки донеслась весёлая песенка: «Рисовый шарик покатился, прямо в норку провалился!»"}},{"t":[[["「"],["おや","おや"],["、"],["ここ","ここ"],["は","は"]],[["ねずみ","ねずみ"],["の","の"]],[["家","いえ"],["です","です"],["か","か"],["。"],["」"],["おじいさん","おじいさん"],["は","は"]],[["穴","あな"],["の","の"]],[["中","なか"],["を","を"]],[["見ました","みました","見る",2],["。"],["その","その"]],[["とき","とき"],["、"],["おじいさん","おじいさん"],["も","も"]],[["穴","あな"],["に","に"]],[["落ちました","おちました","落ちる",2],["。"],["穴","あな"],["の","の"]],[["下","した"],["で","で"],["は","は"],["、"],["白い","しろい"]],[["ねずみ","ねずみ"],["が","が"],["「"],["よう","よう","よい"],["こそ","こそ"],["。"],["こちら","こちら"],["へ","へ"]],[["来て","きて","来る",3]],[["ください","ください","くださる",10],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"«Bura siçanların evidir?» Baba dəliyin içinə baxdı. Elə həmin an özü də dəliyə düşdü. Aşağıda ağ bir siçan dedi: «Xoş gəlmisiniz. Buyurun, bura gəlin».","en":"\"Oh, is this a mouse's home?\" The old man looked into the hole. Just then, he fell in too. At the bottom, a white mouse said, \"Welcome. Please come this way.\"","ru":"«Ой, здесь живут мыши?» Дедушка заглянул в норку. В этот миг он и сам туда упал. Внизу белая мышка сказала: «Добро пожаловать. Проходите сюда, пожалуйста»."}},{"t":[[["おじいさん","おじいさん"],["は","は"]],[["ねずみ","ねずみ"],["と","と"]],[["長い","ながい"]],[["廊下","ろうか"],["を","を"]],[["歩きました","あるきました","歩く",2],["。"],["「"],["電車","でんしゃ"],["で","で","だ"]],[["来ました","きました","来る",2],["か","か"],["。"],["バス","バス"],["で","で","だ"]],[["来ました","きました","来る",2],["か","か"],["。"],["」"],["「"],["いいえ","いいえ"],["、"],["歩いて","あるいて","歩く",3]],[["山","やま"],["へ","へ"]],[["来ました","きました","来る",2],["。"],["それから","それから"],["、"],["おむすび","おむすび"],["と","と"]],[["ここ","ここ"],["へ","へ"]],[["来ました","きました","来る",2],["。"],["」"],["ねずみ","ねずみ"],["は","は"]],[["大きな","おおきな"]],[["声","こえ"],["で","で","だ"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Baba siçanla uzun bir dəhlizlə getdi. «Qatarla gəlmisiniz? Avtobusla gəlmisiniz?» «Xeyr, dağa piyada gəlmişəm. Sonra da düyü topası ilə bura gəlmişəm». Siçan bərkdən güldü.","en":"The old man walked down a long hallway with the mouse. \"Did you come by train? Did you come by bus?\" \"No, I came to the mountain on foot. Then I came here with my rice ball.\" The mouse laughed out loud.","ru":"Дедушка прошёл с мышкой по длинному коридору. «Вы приехали на поезде? На автобусе?» «Нет, в горы я пришёл пешком. А сюда я пришёл вместе с рисовым шариком». Мышка громко рассмеялась."}},{"t":[[["奥","おく"],["の","の"]],[["部屋","へや"],["に","に"],["は","は"],["、"],["ねずみ","ねずみ"],["の","の"]],[["家族","かぞく"],["が","が"]],[["いました","いました","いる",2],["。"],["「"],["今日","きょう"],["は","は"]],[["どこ","どこ"],["へ","へ"]],[["行きます","いきます","行く",11],["か","か"],["」"],["と","と"]],[["おじいさん","おじいさん"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["「"],["どこ","どこ"],["へ","へ"],["も","も"]],[["行きません","いきません","行く",6],["。"],["今日","きょう"],["は","は"]],[["お祭り","おまつり"],["です","です"],["よ","よ"],["。"],["」"],["おじいさん","おじいさん"],["は","は"]],[["ねずみたち","ねずみたち"],["と","と"]],[["歌いました","うたいました","歌う",2],["。"]]],"tr":{"az":"İçəridəki otaqda siçanın ailəsi vardı. «Bu gün hara gedirsiniz?» deyə baba soruşdu. «Heç yerə getmirik. Axı bu gün bayramdır!» Baba siçanlarla birlikdə mahnı oxudu.","en":"The mouse's family was in the back room. \"Where are you going today?\" the old man asked. \"We're not going anywhere. It's our festival today!\" The old man sang with the mice.","ru":"В дальней комнате была мышиная семья. «Куда вы сегодня пойдёте?» спросил дедушка. «Никуда не пойдём. У нас сегодня праздник!» Дедушка пел вместе с мышами."}},{"t":[[["「"],["いつ","いつ"]],[["家","いえ"],["へ","へ"]],[["帰ります","かえります","帰る",11],["か","か"],["」"],["と","と"]],[["白い","しろい"]],[["ねずみ","ねずみ"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["「"],["そう","そう"],["です","です"],["ね","ね"],["。"],["もう","もう"]],[["五","ご"],["時","じ"],["です","です"],["。"],["そろそろ","そろそろ"]],[["帰ります","かえります","帰る",11],["。"],["」"],["ねずみ","ねずみ"],["は","は"]],[["おじいさん","おじいさん"],["に","に"]],[["小さい","ちいさい"]],[["箱","はこ"],["を","を"]],[["あげました","あげました","あげる",2],["。"],["おじいさん","おじいさん"],["は","は"]],[["箱","はこ"],["と","と"]],[["一緒","いっしょ"],["に","に"]],[["穴","あな"],["の","の"]],[["外","そと"],["へ","へ"]],[["出ました","でました","出る",2],["。"]]],"tr":{"az":"«Evə nə vaxt qayıdırsınız?» deyə ağ siçan soruşdu. «Hə, görək... Artıq saat beşdir. Yavaş-yavaş qayıdım». Siçan babaya balaca bir qutu verdi. Baba qutunu götürüb dəlikdən çıxdı.","en":"\"When are you going home?\" asked the white mouse. \"Well, let's see. It's already five. It's about time I went home.\" The mouse gave him a little box. The old man climbed out of the hole with it.","ru":"«Когда вы пойдёте домой?» спросила белая мышка. «Ну что ж, уже пять часов. Пора возвращаться». Мышка подарила дедушке маленькую коробку. Дедушка выбрался из норки вместе с коробкой."}},{"t":[[["おじいさん","おじいさん"],["は","は"]],[["山","やま"],["から","から"]],[["家","いえ"],["へ","へ"]],[["帰りました","かえりました","帰る",2],["。"],["箱","はこ"],["の","の"]],[["中","なか"],["に","に"],["は","は"]],[["金","かね"],["の","の"]],[["お金","おかね"],["が","が"]],[["たくさん","たくさん"]],[["ありました","ありました","ある",2],["。"],["でも","でも"],["、"],["おじいさん","おじいさん"],["は","は"]],[["お金","おかね"],["より","より"]],[["ねずみ","ねずみ"],["の","の"]],[["歌","うた"],["の","の"]],[["話","はなし"],["を","を"]],[["しました","しました","する",2],["。"],["おばあさん","おばあさん"],["も","も"]],[["にこにこ","にこにこ"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Baba dağdan evə qayıtdı. Qutunun içində çoxlu qızıl pul vardı. Amma baba puldan çox siçanların mahnısından danışdı. Nənə də gülümsədi.","en":"The old man returned home from the mountain. Inside the box were lots of gold coins. But he talked more about the mice's song than about the money. The old woman smiled too.","ru":"Дедушка вернулся из гор домой. В коробке было много золотых монет. Но дедушка больше рассказывал о мышиной песенке, чем о деньгах. Бабушка тоже улыбалась."}},{"t":[[["次","つぎ"],["の","の"]],[["日","ひ"],["、"],["おじいさん","おじいさん"],["は","は"]],[["おばあさん","おばあさん"],["と","と"]],[["山","やま"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["二人","ふたり"],["は","は"]],[["大きな","おおきな"]],[["おむすび","おむすび"],["を","を"]],[["穴","あな"],["に","に"]],[["入れました","いれました","入れる",2],["。"],["「"],["今日","きょう"],["は","は"]],[["二人","ふたり"],["で","で"]],[["来ました","きました","来る",2],["よ","よ"],["。"],["」"],["穴","あな"],["の","の"]],[["下","した"],["から","から"],["、"],["昨日","きのう"],["より","より"]],[["大きな","おおきな"]],[["歌声","うたごえ"],["が","が"]],[["聞こえました","きこえました","聞こえる",2],["。"]]],"tr":{"az":"Ertəsi gün baba nənə ilə dağa getdi. İkisi birlikdə böyük bir düyü topasını dəliyə saldı. «Bu gün ikimiz gəlmişik!» Dəliyin içindən dünənkindən də gur mahnı səsi eşidildi.","en":"The next day, the old man went to the mountain with the old woman. Together, they put a big rice ball into the hole. \"There are two of us today!\" From below came singing even louder than the day before.","ru":"На следующий день дедушка пошёл в горы вместе с бабушкой. Они опустили в норку большой рисовый шарик. «Сегодня мы пришли вдвоём!» Снизу донеслась песня, ещё громче вчерашней."}}]},{"id":"l05b","ti":[[["星","ほし"],["へ","へ"]],[["行く","いく","行く",5]],[["夜","よる"],["の","の"]],[["電車","でんしゃ"]]],"tt":{"az":"Ulduzlara gedən gecə qatarı","en":"The Night Train to the Stars","ru":"Ночной поезд к звёздам"},"P":[{"t":[[["町","まち"],["の","の"]],[["はずれ","はずれ"],["に","に","だ"],["、"],["小さい","ちいさい"]],[["駅","えき"],["が","が"]],[["ありました","ありました","ある",2],["。"],["ユイ","ユイ"],["は","は"]],[["毎日","まいにち"]],[["自転車","じてんしゃ"],["で","で","だ"]],[["学校","がっこう"],["へ","へ"]],[["行きました","いきました","行く",2],["が","が"],["、"],["その","その"]],[["駅","えき"],["へ","へ"],["は","は"]],[["行きませんでした","いきませんでした","行く",4],["。"],["ある","ある","ある(連体詞)"]],[["夜","よる"],["、"],["駅","えき"],["に","に"]],[["青い","あおい"]],[["電車","でんしゃ"],["が","が"]],[["来ました","きました","来る",2],["。"],["窓","まど"],["の","の"]],[["中","なか"],["に","に"],["は","は"],["、"],["小さい","ちいさい"]],[["星","ほし"],["が","が"]],[["たくさん","たくさん"]],[["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Şəhərin kənarında balaca bir stansiya vardı. Yui hər gün məktəbə velosipedlə gedirdi, amma o stansiyaya getmirdi. Bir gecə stansiyaya mavi bir qatar gəldi. Pəncərələrin arxasında çoxlu balaca ulduz vardı.","en":"There was a little station at the edge of town. Yui went to school by bicycle every day, but she never went to that station. One night, a blue train arrived there. Behind its windows were lots of little stars.","ru":"На окраине города была маленькая станция. Юи каждый день ездила в школу на велосипеде, но на эту станцию не ходила. Однажды ночью туда прибыл синий поезд. За его окнами было множество маленьких звёзд."}},{"t":[[["ユイ","ユイ"],["は","は"]],[["一人","ひとり"],["で","で"]],[["駅","えき"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["白い","しろい"]],[["帽子","ぼうし"],["の","の"]],[["男の子","おとこのこ"],["が","が"]],[["電車","でんしゃ"],["の","の"]],[["前","まえ"],["に","に"]],[["いました","いました","いる",2],["。"],["「"],["この","この"]],[["電車","でんしゃ"],["は","は"]],[["どこ","どこ"],["へ","へ"]],[["行きます","いきます","行く",11],["か","か"],["。"],["」"],["「"],["星","ほし"],["の","の"]],[["学校","がっこう"],["へ","へ"]],[["行きます","いきます","行く",11],["。"],["ぼく","ぼく"],["は","は"]],[["ソラ","ソラ"],["です","です"],["。"],["一緒","いっしょ"],["に","に"]],[["行きましょう","いきましょう","行く",20],["。"],["」"]]],"tr":{"az":"Yui stansiyaya tək getdi. Qatarın qabağında ağ papaqlı bir oğlan vardı. «Bu qatar hara gedir?» «Ulduzların məktəbinə gedir. Mən Sorayam. Gəl birlikdə gedək».","en":"Yui went to the station alone. A boy in a white cap stood in front of the train. \"Where does this train go?\" \"It goes to the school for stars. I'm Sora. Let's go together.\"","ru":"Юи одна пошла на станцию. Перед поездом стоял мальчик в белой фуражке. «Куда идёт этот поезд?» «В школу для звёзд. Меня зовут Сора. Поедем вместе»."}},{"t":[[["ユイ","ユイ"],["は","は"]],[["ソラ","ソラ"],["と","と"]],[["電車","でんしゃ"],["で","で","だ"]],[["空","そら"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["町","まち"],["も","も"]],[["山","やま"],["も","も"],["、"],["もう","もう"]],[["小さく","ちいさく","小さい"]],[["なりました","なりました","なる",2],["。"],["「"],["星","ほし"],["も","も"]],[["電車","でんしゃ"],["で","で","だ"]],[["学校","がっこう"],["へ","へ"]],[["行きます","いきます","行く",11],["か","か"],["。"],["」"],["「"],["ええ","ええ"],["。"],["月","つき"],["の","の"]],[["向こう","むこう"],["の","の"]],[["学校","がっこう"],["です","です"],["よ","よ"],["。"],["」"],["座席","ざせき"],["の","の"]],[["星たち","ほしたち"],["は","は"]],[["ぴかぴか","ぴかぴか"]],[["光りました","ひかりました","光る",2],["。"]]],"tr":{"az":"Yui Sora ilə qatarla göyə qalxdı. Şəhər də, dağlar da artıq balaca görünürdü. «Ulduzlar da məktəbə qatarla gedirlər?» «Bəli. Məktəb Ayın o biri tərəfindədir!» Oturacaqlardakı ulduzlar parıldadı.","en":"Yui went up into the sky by train with Sora. The town and mountains already looked tiny. \"Do stars go to school by train too?\" \"Yes. Their school is on the other side of the moon!\" The stars on the seats twinkled.","ru":"Юи вместе с Сорой отправилась на поезде в небо. Город и горы уже казались крошечными. «Звёзды тоже ездят в школу на поезде?» «Да. Их школа по ту сторону Луны!» Звёздочки на сиденьях засияли."}},{"t":[[["でも","でも"],["、"],["月","つき"],["の","の"]],[["前","まえ"],["で","で"]],[["電車","でんしゃ"],["は","は"]],[["止まりました","とまりました","止まる",2],["。"],["ソラ","ソラ"],["は","は"]],[["黒い","くろい"]],[["空","そら"],["を","を"]],[["見ました","みました","見る",2],["。"],["「"],["次","つぎ"],["の","の"]],[["駅","えき"],["の","の"]],[["明かり","あかり"],["が","が"]],[["ありません","ありません","ある",6],["。"],["駅","えき"],["は","は"]],[["どこ","どこ"],["でしょう","でしょう","です"],["。"],["」"],["星たち","ほしたち"],["も","も"]],[["窓","まど"],["の","の"]],[["外","そと"],["を","を"]],[["見ました","みました","見る",2],["が","が"],["、"],["駅","えき"],["は","は"]],[["ありませんでした","ありませんでした","ある",4],["。"]]],"tr":{"az":"Amma qatar Ayın qabağında dayandı. Sora qaranlıq göyə baxdı. «Növbəti stansiyanın işığı yanmır. Görəsən, stansiya haradadır?» Ulduzlar da pəncərədən çölə baxdılar, amma stansiya görünmürdü.","en":"But the train stopped in front of the moon. Sora looked into the dark sky. \"The next station's light is out. Where could the station be?\" The stars looked out of the windows too, but there was no station in sight.","ru":"Но перед Луной поезд остановился. Сора посмотрел в тёмное небо. «На следующей станции не горит свет. Где же она?» Звёздочки тоже выглянули в окна, но станции нигде не было видно."}},{"t":[[["一番","いちばん"]],[["小さい","ちいさい"]],[["星","ほし"],["が","が"],["、"],["ユイ","ユイ"],["の","の"]],[["隣","となり"],["に","に"]],[["いました","いました","いる",2],["。"],["「"],["ぼく","ぼく"],["は","は"]],[["学校","がっこう"],["へ","へ"]],[["行きません","いきません","行く",6],["。"],["どこ","どこ"],["へ","へ"],["も","も"]],[["行きません","いきません","行く",6],["。"],["ぼく","ぼく"],["の","の"]],[["光","ひかり"],["は","は"]],[["小さい","ちいさい"],["です","です"],["から","から"],["。"],["」"],["ユイ","ユイ"],["は","は"]],[["小さい","ちいさい"]],[["星","ほし"],["を","を"]],[["見ました","みました","見る",2],["。"],["その","その"]],[["光","ひかり"],["は","は"]],[["黄色くて","きいろくて","黄色い",3],["、"],["温かい","あたたかい"]],[["光","ひかり"],["でした","でした","です",9],["。"]]],"tr":{"az":"Ən balaca ulduz Yuinin yanında idi. «Mən məktəbə getmirəm. Heç yerə getmirəm. Çünki işığım çox zəifdir». Yui balaca ulduza baxdı. Onun işığı sarı və isti idi.","en":"The smallest star was beside Yui. \"I'm not going to school. I'm not going anywhere. My light is too small.\" Yui looked at the little star. Its light was yellow and warm.","ru":"Самая маленькая звёздочка была рядом с Юи. «Я не поеду в школу. Никуда не поеду. Ведь мой свет совсем слабый». Юи посмотрела на звёздочку. Её свет был жёлтым и тёплым."}},{"t":[[["「"],["一緒","いっしょ"],["に","に"]],[["前","まえ"],["へ","へ"]],[["行きましょう","いきましょう","行く",20],["。"],["あなた","あなた"],["の","の"]],[["光","ひかり"],["も","も"]],[["大切","たいせつ"],["です","です"],["よ","よ"],["。"],["」"],["ユイ","ユイ"],["は","は"]],[["小さい","ちいさい"]],[["星","ほし"],["と","と"]],[["運転","うんてん"],["席","せき"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["黄色い","きいろい"]],[["光","ひかり"],["の","の"]],[["中","なか"],["に","に"],["、"],["駅","えき"],["の","の"]],[["名前","なまえ"],["が","が"]],[["見えました","みえました","見える",2],["。"],["「"],["あ","あ"],["、"],["ここ","ここ"],["です","です"],["！"],["」"],["ソラ","ソラ"],["は","は"]],[["ゆっくり","ゆっくり"]],[["電車","でんしゃ"],["を","を"]],[["動かしました","うごかしました","動かす",2],["。"]]],"tr":{"az":"«Gəl birlikdə qabağa gedək. Sənin işığın da vacibdir!» Yui balaca ulduzla maşinistin kabinəsinə getdi. Sarı işıqda stansiyanın adı göründü. «Bax, buradadır!» Sora qatarı yavaş-yavaş hərəkətə gətirdi.","en":"\"Let's go to the front together. Your light matters too!\" Yui went to the driver's cab with the little star. In its yellow light, the station's name became visible. \"Ah, here it is!\" Sora slowly moved the train forward.","ru":"«Пойдём вместе вперёд. Твой свет тоже важен!» Юи прошла с маленькой звёздочкой в кабину машиниста. В жёлтом свете показалось название станции. «А, вот она!» Сора медленно повёл поезд вперёд."}},{"t":[[["星たち","ほしたち"],["は","は"]],[["駅","えき"],["から","から"]],[["歩いて","あるいて","歩く",3]],[["学校","がっこう"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["小さい","ちいさい"]],[["星","ほし"],["も","も"]],[["友達","ともだち"],["と","と"]],[["行きました","いきました","行く",2],["。"],["「"],["ユイさん","ユイさん"],["は","は"]],[["いつ","いつ"]],[["家","いえ"],["へ","へ"]],[["帰ります","かえります","帰る",11],["か","か"],["」"],["と","と"]],[["ソラ","ソラ"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["「"],["そう","そう"],["です","です"],["ね","ね"],["。"],["朝","あさ"],["の","の"]],[["六","ろく"],["時","じ"],["に","に"]],[["母","はは"],["と","と"]],[["朝ご飯","あさごはん"],["を","を"]],[["食べます","たべます","食べる",11],["。"],["」"]]],"tr":{"az":"Ulduzlar stansiyadan məktəbə piyada getdilər. Balaca ulduz da dostları ilə getdi. «Yui, sən evə nə vaxt qayıdırsan?» deyə Sora soruşdu. «Hə, görək... Səhər saat altıda anamla səhər yeməyi yeyirəm».","en":"The stars walked from the station to school. The little star went with its friends too. \"When are you going home, Yui?\" Sora asked. \"Well, let's see. I have breakfast with my mother at six in the morning.\"","ru":"Звёзды пошли от станции до школы пешком. Маленькая звёздочка тоже пошла вместе с друзьями. «Юи, когда ты возвращаешься домой?» спросил Сора. «Ну, утром в шесть я завтракаю с мамой»."}},{"t":[[["ユイ","ユイ"],["は","は"]],[["青い","あおい"]],[["電車","でんしゃ"],["で","で","だ"]],[["町","まち"],["へ","へ"]],[["帰りました","かえりました","帰る",2],["。"],["朝","あさ"],["、"],["ポケット","ポケット"],["に","に"]],[["小さい","ちいさい"]],[["切符","きっぷ"],["が","が"]],[["ありました","ありました","ある",2],["。"],["切符","きっぷ"],["に","に"],["は","は"],["「"],["次","つぎ"],["は","は"]],[["お母さん","おかあさん"],["と","と"],["」"],["と","と"]],[["ありました","ありました","ある",2],["。"],["その","その"]],[["夜","よる"],["、"],["空","そら"],["の","の"]],[["黄色い","きいろい"]],[["星","ほし"],["が","が"],["、"],["二回","にかい"]],[["ぴかぴか","ぴかぴか"]],[["光りました","ひかりました","光る",2],["。"]]],"tr":{"az":"Yui mavi qatarla şəhərə qayıtdı. Səhər cibində balaca bir bilet vardı. Biletin üstündə «Gələn dəfə ananla» yazılmışdı. Həmin gecə göydəki sarı ulduz iki dəfə yanıb-söndü.","en":"Yui returned to town on the blue train. In the morning, there was a little ticket in her pocket. It said, \"Next time, with your mother.\" That night, the yellow star in the sky twinkled twice.","ru":"Юи вернулась в город на синем поезде. Утром в её кармане оказался маленький билет. На нём было написано: «В следующий раз с мамой». В ту ночь жёлтая звёздочка в небе мигнула два раза."}}]},{"id":"l05c","ti":[[["おばあちゃん","おばあちゃん"],["の","の"]],[["秘密","ひみつ"],["の","の"]],[["行き先","いきさき"]]],"tt":{"az":"Nənənin gizli getdiyi yer","en":"Grandma's Secret Destination","ru":"Куда тайком ездила бабушка"},"P":[{"t":[[["土曜","どよう"],["日","ひ"],["の","の"]],[["朝","あさ"],["、"],["ケンタ","ケンタ"],["は","は"]],[["おばあちゃん","おばあちゃん"],["の","の"]],[["家","いえ"],["へ","へ"]],[["自転車","じてんしゃ"],["で","で","だ"]],[["行きました","いきました","行く",2],["。"],["おばあちゃん","おばあちゃん"],["の","の"]],[["誕生","たんじょう"],["日","ひ"],["は","は"]],[["来週","らいしゅう"],["でした","でした","です",9],["。"],["去年","きょねん"],["は","は"]],[["家族","かぞく"],["と","と"]],[["海","うみ"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["今年","ことし"],["も","も"]],[["ケンタ","ケンタ"],["は","は"]],[["おばあちゃん","おばあちゃん"],["と","と"]],[["旅行","りょこう"],["へ","へ"]],[["行きたかった","いきたかった","行く",21],["の","の"],["です","です"],["。"]]],"tr":{"az":"Şənbə səhəri Kenta nənəsinin evinə velosipedlə getdi. Nənəsinin ad günü gələn həftə idi. Keçən il ailəlikcə dənizə getmişdilər. Bu il də Kenta nənəsi ilə səyahətə çıxmaq istəyirdi.","en":"On Saturday morning, Kenta went to Grandma's house by bicycle. Her birthday was the following week. Last year, she had gone to the seaside with the family. This year, Kenta wanted to go on a trip with her again.","ru":"В субботу утром Кэнта поехал к бабушке на велосипеде. На следующей неделе у неё был день рождения. В прошлом году она ездила с семьёй на море. В этом году Кэнта снова хотел отправиться с ней в путешествие."}},{"t":[[["「"],["誕生","たんじょう"],["日","ひ"],["は","は"]],[["どこ","どこ"],["へ","へ"]],[["行きます","いきます","行く",11],["か","か"],["。"],["船","ふね"],["で","で","だ"]],[["島","しま"],["へ","へ"]],[["行きません","いきません","行く",6],["か","か"],["。"],["」"],["でも","でも"],["、"],["おばあちゃん","おばあちゃん"],["は","は"]],[["首","くび"],["を","を"]],[["横","よこ"],["に","に"]],[["振りました","ふりました","振る",2],["。"],["「"],["ありがとう","ありがとう"],["。"],["でも","でも"],["、"],["来週","らいしゅう"],["は","は"]],[["どこ","どこ"],["へ","へ"],["も","も"]],[["行きません","いきません","行く",6],["。"],["」"],["ケンタ","ケンタ"],["は","は"]],[["少し","すこし"]],[["がっかり","がっかり"]],[["しました","しました","する",2],["。"]]],"tr":{"az":"«Ad günündə hara gedirsən? Gəmi ilə adaya gedək?» Amma nənəsi başını buladı. «Sağ ol. Amma gələn həftə heç yerə getmirəm». Kenta bir az məyus oldu.","en":"\"Where are you going for your birthday? Shall we go to an island by boat?\" But Grandma shook her head. \"Thank you. But I'm not going anywhere next week.\" Kenta felt a little disappointed.","ru":"«Куда ты поедешь на день рождения? Может, отправимся на остров на корабле?» Но бабушка покачала головой. «Спасибо. Но на следующей неделе я никуда не поеду». Кэнта немного расстроился."}},{"t":[[["その","その"]],[["とき","とき"],["、"],["電話","でんわ"],["が","が"]],[["鳴りました","なりました","鳴る",2],["。"],["「"],["ええ","ええ"],["、"],["駅","えき"],["へ","へ"]],[["十","じゅう"],["時","じ"],["に","に"]],[["行きます","いきます","行く",11],["。"],["今日","きょう"],["は","は"]],[["電車","でんしゃ"],["です","です"],["ね","ね"],["。"],["」"],["おばあちゃん","おばあちゃん"],["は","は"]],[["小さい","ちいさい"]],[["かばん","かばん"],["を","を"]],[["持ちました","もちました","持つ",2],["。"],["ケンタ","ケンタ"],["は","は"]],[["不思議","ふしぎ"],["に","に","だ"]],[["思いました","おもいました","思う",2],["。"],["かばん","かばん"],["に","に"],["は","は"]],[["赤い","あかい"]],[["靴","くつ"],["が","が"]],[["入って","はいって","入る",3]],[["いました","いました","いる",2],["。"]]],"tr":{"az":"Elə bu vaxt telefon zəng çaldı. «Bəli, saat onda stansiyaya gəlirəm. Bu gün qatarla gedirik, eləmi?» Nənəsi balaca bir çanta götürdü. Kenta təəccübləndi. Çantada qırmızı ayaqqabılar vardı.","en":"Just then, the telephone rang. \"Yes, I'll go to the station at ten. We're taking the train today, right?\" Grandma picked up a little bag. Kenta was puzzled. There were red shoes inside it.","ru":"В этот момент зазвонил телефон. «Да, приду на станцию к десяти. Сегодня едем на поезде, верно?» Бабушка взяла маленькую сумку. Кэнта удивился. В сумке лежали красные туфли."}},{"t":[[["「"],["おばあちゃん","おばあちゃん"],["、"],["今日","きょう"],["は","は"]],[["どこ","どこ"],["へ","へ"]],[["行きます","いきます","行く",11],["か","か"],["。"],["」"],["「"],["ちょっと","ちょっと"]],[["学校","がっこう"],["へ","へ"]],[["行きます","いきます","行く",11],["。"],["友達","ともだち"],["と","と"]],[["行きます","いきます","行く",11],["よ","よ"],["。"],["」"],["ケンタ","ケンタ"],["は","は"]],[["もっと","もっと"]],[["不思議","ふしぎ"],["に","に","だ"]],[["思いました","おもいました","思う",2],["。"],["おばあちゃん","おばあちゃん"],["は","は"]],[["七十歳","ななじゅうさい"],["でした","でした","です",9],["が","が"],["、"],["今日","きょう"],["は","は"]],[["学生","がくせい"],["の","の"]],[["よう","よう"],["でした","でした","です",9],["。"]]],"tr":{"az":"«Nənə, bu gün hara gedirsən?» «Bir az məktəbə gedirəm. Dostlarımla gedirəm!» Kenta lap təəccübləndi. Nənəsinin yetmiş yaşı vardı, amma bu gün lap şagirdə oxşayırdı.","en":"\"Grandma, where are you going today?\" \"Just to school for a little while. I'm going with my friends!\" Kenta was even more puzzled. Grandma was seventy, but today she seemed like a student.","ru":"«Бабушка, куда ты сегодня идёшь?» «Ненадолго в школу. Иду с друзьями!» Кэнта удивился ещё больше. Бабушке было семьдесят лет, но сегодня она была похожа на ученицу."}},{"t":[[["「"],["ぼく","ぼく"],["も","も"]],[["一緒","いっしょ"],["に","に"]],[["行きます","いきます","行く",11],["。"],["」"],["二人","ふたり"],["は","は"]],[["駅","えき"],["まで","まで"]],[["歩いて","あるいて","歩く",3]],[["行きました","いきました","行く",2],["。"],["駅","えき"],["に","に"],["は","は"],["、"],["おじいさん","おじいさん"],["が","が"]],[["三人","さんにん"]],[["いました","いました","いる",2],["。"],["みんな","みんな"],["の","の"]],[["かばん","かばん"],["に","に"],["も","も"]],[["赤い","あかい"]],[["靴","くつ"],["が","が"]],[["ありました","ありました","ある",2],["。"],["五人","ごにん"],["は","は"]],[["電車","でんしゃ"],["で","で","だ"]],[["隣","となり"],["の","の"]],[["町","まち"],["へ","へ"]],[["行きました","いきました","行く",2],["。"]]],"tr":{"az":"«Mən də səninlə gedirəm». İkisi stansiyaya piyada getdi. Stansiyada üç baba vardı. Onların da hər birinin çantasında qırmızı ayaqqabılar vardı. Beşlikdə qatarla qonşu şəhərə getdilər.","en":"\"I'll come with you.\" They walked to the station together. Three elderly men were waiting there. Each of their bags had red shoes inside too. The five of them took the train to the next town.","ru":"«Я тоже пойду с тобой». Они вдвоём дошли до станции пешком. Там ждали трое дедушек. У каждого в сумке тоже были красные туфли. Впятером они поехали на поезде в соседний город."}},{"t":[[["「"],["いつ","いつ"],["から","から"]],[["学校","がっこう"],["へ","へ"]],[["行って","いって","行く",3]],[["います","います","いる",11],["か","か"],["」"],["と","と"]],[["ケンタ","ケンタ"],["が","が"]],[["聞きました","ききました","聞く",2],["。"],["「"],["先週","せんしゅう"],["から","から"],["です","です"],["よ","よ"],["。"],["」"],["「"],["何","なん"],["の","の"]],[["学校","がっこう"],["です","です"],["か","か"],["。"],["」"],["おばあちゃん","おばあちゃん"],["は","は"]],[["笑いました","わらいました","笑う",2],["。"],["「"],["そう","そう"],["です","です"],["ね","ね"],["。"],["学校","がっこう"],["で","で","だ"]],[["答え","こたえ"],["が","が"]],[["わかります","わかります","わかる",11],["よ","よ"],["。"],["」"]]],"tr":{"az":"«Nə vaxtdan məktəbə gedirsən?» deyə Kenta soruşdu. «Keçən həftədən!» «Nə məktəbidir?» Nənəsi gülümsədi. «Hə, məktəbə çatanda cavabını biləcəksən».","en":"\"When did you start going to school?\" Kenta asked. \"Last week!\" \"What kind of school is it?\" Grandma smiled. \"Well, you'll find the answer at school.\"","ru":"«С каких пор ты ходишь в школу?» спросил Кэнта. «С прошлой недели!» «А что это за школа?» Бабушка улыбнулась. «Ну что ж, в школе узнаешь ответ»."}},{"t":[[["学校","がっこう"],["の","の"]],[["部屋","へや"],["で","で"],["は","は"],["、"],["音楽","おんがく"],["が","が"]],[["流れて","ながれて","流れる",3]],[["いました","いました","いる",2],["。"],["おばあちゃんたち","おばあちゃんたち"],["は","は"]],[["赤い","あかい"]],[["靴","くつ"],["で","で","だ"]],[["ダンス","ダンス"],["を","を"]],[["しました","しました","する",2],["。"],["ケンタ","ケンタ"],["は","は"]],[["びっくり","びっくり"]],[["しました","しました","する",2],["。"],["「"],["来週","らいしゅう"],["、"],["みんな","みんな"],["が","が"]],[["私","わたし"],["の","の"]],[["家","いえ"],["へ","へ"]],[["来ます","きます","来る",11],["。"],["誕生","たんじょう"],["日","ひ"],["に","に"]],[["ダンス","ダンス"],["を","を"]],[["します","します","する",11],["よ","よ"],["。"],["」"]]],"tr":{"az":"Məktəbin otağında musiqi səslənirdi. Nənəsi ilə dostları qırmızı ayaqqabılarla rəqs etdilər. Kenta heyrətləndi. «Gələn həftə hamı mənim evimə gəlir. Ad günümdə rəqs edəcəyik!»","en":"Music was playing in a room at the school. Grandma and her friends danced in their red shoes. Kenta was amazed. \"Everyone is coming to my house next week. We're going to dance on my birthday!\"","ru":"В комнате школы играла музыка. Бабушка и её друзья танцевали в красных туфлях. Кэнта был поражён. «На следующей неделе все придут ко мне домой. На мой день рождения будем танцевать!»"}},{"t":[[["帰り","かえり"],["も","も"]],[["ケンタ","ケンタ"],["は","は"]],[["おばあちゃん","おばあちゃん"],["と","と"]],[["電車","でんしゃ"],["で","で","だ"]],[["帰りました","かえりました","帰る",2],["。"],["「"],["誕生","たんじょう"],["日","ひ"],["は","は"]],[["ぼく","ぼく"],["も","も"]],[["どこ","どこ"],["へ","へ"],["も","も"]],[["行きません","いきません","行く",6],["。"],["おばあちゃん","おばあちゃん"],["と","と"]],[["踊ります","おどります","踊る",11],["。"],["」"],["次","つぎ"],["の","の"]],[["土曜","どよう"],["日","ひ"],["、"],["ケンタ","ケンタ"],["は","は"]],[["また","また"]],[["自転車","じてんしゃ"],["で","で","だ"]],[["来ました","きました","来る",2],["。"],["かばん","かばん"],["の","の"]],[["中","なか"],["に","に"],["は","は"],["、"],["小さい","ちいさい"]],[["赤い","あかい"]],[["靴","くつ"],["が","が"]],[["ありました","ありました","ある",2],["。"]]],"tr":{"az":"Geri qayıdanda da Kenta nənəsi ilə qatarla gəldi. «Sənin ad günündə mən də heç yerə getmirəm. Səninlə rəqs edəcəyəm». Növbəti şənbə Kenta yenə velosipedlə gəldi. Çantasının içində balaca qırmızı ayaqqabılar vardı.","en":"Kenta took the train home with Grandma too. \"I'm not going anywhere on your birthday either. I'll dance with you.\" The next Saturday, Kenta came by bicycle again. Inside his bag was a little pair of red shoes.","ru":"Обратно Кэнта тоже ехал с бабушкой на поезде. «В твой день рождения я тоже никуда не пойду. Буду танцевать с тобой». В следующую субботу Кэнта снова приехал на велосипеде. В его сумке лежали маленькие красные туфли."}}]}],"G":{"あ":{"b":"あ","p":"in","m":{"az":"A!; Ah!","en":"Ah!; Oh!","ru":"А!; О!"},"n":{"az":"Nəyisə görməyi, xatırlamağı və ya qəfil başa düşməyi bildirə bilər.","en":"Can signal noticing, remembering, or suddenly understanding something.","ru":"Может выражать узнавание, воспоминание или внезапное понимание."}},"あげる":{"b":"あげる","p":"v","m":{"az":"vermək, hədiyyə etmək","en":"give","ru":"давать, дарить"},"n":{"az":"Alan şəxs に, verilən şey を ilə işlənir: 友達に本をあげる; danışana verilən şey üçün adətən くれる işlənir.","en":"The recipient takes に and the gift を, as in 友達に本をあげる; giving to the speaker is usually expressed with くれる.","ru":"Получатель обозначается с に, подарок с を: 友達に本をあげる; когда дают говорящему, обычно используется くれる."}},"あなた":{"b":"あなた","p":"pr","m":{"az":"sən, siz","en":"you","ru":"ты, вы"},"n":{"az":"Yaponcada adamı adı ilə çağırmaq daha nəzakətlidir (ケンさん). あなた bəzən soyuq səslənir.","en":"Calling people by name (ケンさん) is more polite; あなた can sound cold.","ru":"Вежливее обращаться по имени (ケンさん); あなた может звучать холодно."}},"ありがとう":{"b":"ありがとう","p":"ex","m":{"az":"sağ ol","en":"thank you","ru":"спасибо"},"n":{"az":"Daha nəzakətli: ありがとうございます.","en":"More polite: ありがとうございます.","ru":"Вежливее: ありがとうございます."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"いいえ":{"b":"いいえ","p":"in","m":{"az":"xeyr, yox","en":"no","ru":"нет"}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"ええ":{"b":"ええ","p":"in","m":{"az":"bəli; hə","en":"yes","ru":"да"},"n":{"az":"Danışıqda işlənən təsdiqdir, はい-dan daha az rəsmidir.","en":"A conversational yes, less formal than はい.","ru":"Разговорное «да», менее официальное, чем はい."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おばあちゃん":{"b":"おばあちゃん","p":"n","m":{"az":"nənə; yaşlı qadın","en":"grandma; elderly woman","ru":"бабушка; пожилая женщина"},"n":{"az":"Nənəyə və ya yaşlı qadına mehriban müraciət kimi də işlənir.","en":"Also used as an affectionate address to a grandmother or elderly woman.","ru":"Также используется как ласковое обращение к бабушке или пожилой женщине."}},"おばあちゃんたち":{"b":"おばあちゃん","p":"n","m":{"az":"nənələr; yaşlı qadınlar","en":"grandmothers; elderly women","ru":"бабушки; пожилые женщины"},"n":{"az":"たち bir neçə nənəni və ya nənə ilə birlikdə olan qrupu göstərə bilər.","en":"たち can mean several grandmothers or a grandmother and her group.","ru":"たち может обозначать нескольких бабушек или бабушку и её компанию."}},"おむすび":{"b":"おむすび","p":"n","m":{"az":"düyü topası","en":"rice ball","ru":"рисовый колобок; онигири"}},"おや":{"b":"おや","p":"in","m":{"az":"oho; aa","en":"oh; well now","ru":"о; надо же"},"n":{"az":"Təəccüb və ya yeni bir şeyi görməyi bildirir.","en":"Expresses mild surprise or noticing something.","ru":"Выражает лёгкое удивление или обнаружение чего-либо."}},"お昼ご飯":{"b":"お昼ご飯 (おひるごはん)","p":"n","m":{"az":"nahar; günorta yeməyi","en":"lunch","ru":"обед"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 昼ご飯 ilə mənası eynidir.","en":"お is a polite prefix; the meaning is the same as 昼ご飯.","ru":"お является вежливой приставкой; значение совпадает с 昼ご飯."}},"お母さん":{"b":"お母さん (おかあさん)","p":"n","m":{"az":"ana","en":"mother; mom","ru":"мама; мать"},"n":{"az":"Anaya müraciətdə və başqasının anası haqqında işlənir; kənar şəxslərə öz anandan danışarkən adətən 母 deyilir.","en":"Used to address your mother or refer to someone else's; use 母 for your own mother when speaking to outsiders.","ru":"Используется при обращении к маме или о чужой матери; о своей матери посторонним обычно говорят 母."}},"お祭り":{"b":"お祭り (おまつり)","p":"n","m":{"az":"bayram; festival","en":"festival; celebration","ru":"праздник; фестиваль"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 祭り də işlənir.","en":"お is a polite prefix; 祭り is also used.","ru":"お является вежливой приставкой; также употребляется 祭り."}},"お金":{"b":"お金 (おかね)","p":"n","m":{"az":"pul","en":"money","ru":"деньги"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かばん":{"b":"鞄 (かばん)","p":"n","m":{"az":"çanta","en":"bag","ru":"сумка"}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"がっかり":{"b":"がっかり","p":"ad","m":{"az":"məyus halda","en":"disappointed; dejected","ru":"разочарованно; уныло"},"n":{"az":"Adətən がっかりする formasında işlənir: məyus olmaq.","en":"Usually used as がっかりする, meaning to be disappointed.","ru":"Обычно употребляется в форме がっかりする: разочаровываться."}},"くださる":{"b":"ください","p":"ex","m":{"az":"zəhmət olmasa (...edin)","en":"please (do ...)","ru":"пожалуйста (сделайте)"},"n":{"az":"Feilin te-formasından sonra nəzakətli xahiş: 見てください = baxın, zəhmət olmasa.","en":"After a te-form it makes a polite request: 見てください = please look.","ru":"После формы на -te – вежливая просьба: 見てください = посмотрите, пожалуйста."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こそ":{"b":"こそ","p":"pt","m":{"az":"məhz; elə","en":"precisely; the very","ru":"именно; как раз"},"n":{"az":"Vurğu yaradır: 今年こそ = məhz bu il; こちらこそ = mən də sizə.","en":"Adds emphasis: 今年こそ = this year for sure; こちらこそ = likewise on my part.","ru":"Усиливает выделение: 今年こそ = именно в этом году; こちらこそ = это я вас благодарю."}},"こちら":{"b":"こちら","p":"pr","m":{"az":"bura, bu tərəf","en":"here, this way","ru":"здесь, эта сторона"},"n":{"az":"Nəzakətli nitqdə “bu şəxs” və “bizim tərəf” mənalarında da işlənir.","en":"In polite speech, it can also mean “this person” or “our side.”","ru":"В вежливой речи также означает «этот человек» или «наша сторона»."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"ころころ":{"b":"ころころ","p":"ad","m":{"az":"diyirlənə-diyirlənə","en":"rolling over and over","ru":"кувырком; перекатываясь"},"n":{"az":"Kiçik, yumru əşyanın təkrar diyirlənməsini təsvir edən təqlidi sözdür.","en":"A mimetic word for a small round object rolling repeatedly.","ru":"Образное слово для многократного перекатывания небольшого круглого предмета."}},"ころりん":{"b":"ころりん","p":"ad","m":{"az":"hop, diyirləndi","en":"with a little roll or tumble","ru":"кувырк; покатился"},"n":{"az":"Nağıl dilində yüngül diyirlənməni bildirən oynaq təqlidi sözdür.","en":"A playful storybook word suggesting a little roll or tumble.","ru":"Игривое сказочное слово, передающее лёгкое перекатывание или кувырок."}},"すっとんとん":{"b":"すっとんとん","p":"ad","m":{"az":"tup-tup-tup","en":"tump-tump-tump","ru":"топ-топ-топ"},"n":{"az":"Nağıldakı nəqarətdə ritmik səs təqlididir, sabit lüğəvi mənası yoxdur.","en":"A rhythmic sound imitation in a story refrain, without a fixed lexical meaning.","ru":"Ритмическое звукоподражание в сказочном припеве без постоянного словарного значения."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それから":{"b":"それから","p":"cj","m":{"az":"sonra, ondan sonra","en":"then, after that","ru":"потом, затем"}},"そろそろ":{"b":"そろそろ","p":"ad","m":{"az":"artıq vaxtıdır; yavaş-yavaş","en":"about time; gradually","ru":"уже пора; постепенно"},"n":{"az":"そろそろ帰ります ifadəsində getmək vaxtının çatdığını bildirir.","en":"In そろそろ帰ります, it signals that it is about time to leave.","ru":"В выражении そろそろ帰ります показывает, что уже пора уходить."}},"たくさん":{"b":"たくさん","p":"ad","m":{"az":"çox; çoxlu","en":"many; much; a lot","ru":"много"},"n":{"az":"İsimlə たくさんの本, fellə isə たくさん食べる şəklində işlənir.","en":"Use たくさんの本 with a noun and たくさん食べる with a verb.","ru":"С существительным употребляется たくさんの本, с глаголом たくさん食べる."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"ちょっと":{"b":"ちょっと","p":"ad","m":{"az":"bir az; bir an","en":"a little; a moment","ru":"немного; минутку"},"n":{"az":"Xahişi yumşaldır: ちょっと待ってください; tərəddüdlü cavabda nəzakətli imtina da ola bilər.","en":"Softens requests: ちょっと待ってください; in a hesitant reply it can signal a polite refusal.","ru":"Смягчает просьбы: ちょっと待ってください; в нерешительном ответе может выражать вежливый отказ."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"どこ":{"b":"どこ","p":"pr","m":{"az":"hara","en":"where","ru":"где, куда"},"n":{"az":"どこの国 = hansı ölkə.","en":"どこの国 = which country.","ru":"どこの国 = какая страна."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にこにこ":{"b":"にこにこ","p":"ad","m":{"az":"gülümsəyərək","en":"with a cheerful smile","ru":"с улыбкой"},"n":{"az":"にこにこする = gülümsəmək, adətən səssiz və şən şəkildə.","en":"にこにこする means to smile cheerfully, usually without laughing aloud.","ru":"にこにこする означает приветливо улыбаться, обычно без громкого смеха."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"ねずみ":{"b":"ねずみ","p":"n","m":{"az":"siçan; siçovul","en":"mouse; rat","ru":"мышь; крыса"}},"ねずみたち":{"b":"ねずみ","p":"n","m":{"az":"siçanlar","en":"mice","ru":"мыши"},"n":{"az":"たち burada siçanların bir qrup olduğunu göstərir.","en":"たち marks a group of mice here.","ru":"たち здесь обозначает группу мышей."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"はずれ":{"b":"はずれ","p":"n","m":{"az":"kənar; ucqar hissə","en":"edge; outskirts","ru":"край; окраина"},"n":{"az":"村のはずれ = kəndin kənarı; başqa kontekstdə uduşsuz nəticə də bildirir.","en":"村のはずれ means the edge of a village; elsewhere it can mean a losing result.","ru":"村のはずれ означает окраину деревни; в другом контексте может означать проигрыш."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"ぴかぴか":{"b":"ぴかぴか","p":"ad","m":{"az":"par-par; parıldayan","en":"sparkling; shiny","ru":"блестящий; сверкающий"},"n":{"az":"ぴかぴか光る parıldamaq, ぴかぴかの isə parlaq və ya təzə görünən deməkdir.","en":"ぴかぴか光る means to sparkle; ぴかぴかの describes something shiny or new-looking.","ru":"ぴかぴか光る значит сверкать, а ぴかぴかの описывает блестящий или выглядящий новым предмет."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ぼく":{"b":"僕 (ぼく)","p":"pr","m":{"az":"mən","en":"I","ru":"я"},"n":{"az":"Əsasən oğlanların və kişilərin işlətdiyi birinci şəxs əvəzliyidir.","en":"A first-person pronoun used mainly by boys and men.","ru":"Местоимение первого лица, употребляемое преимущественно мальчиками и мужчинами."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかし":{"b":"昔 (むかし)","p":"n","m":{"az":"çox qədim zaman","en":"long ago","ru":"давным-давно"},"n":{"az":"むかし むかし = 'biri var idi, biri yox idi' – nağılların başlanğıcı.","en":"むかし むかし = 'once upon a time' – the opening of tales.","ru":"むかし むかし = 'давным-давно' – начало сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もっと":{"b":"もっと","p":"ad","m":{"az":"daha, daha çox","en":"more","ru":"больше, ещё"}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よい":{"b":"よい","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"い-sifətidir və いい ilə eynimənalıdır; よう bəzi ifadələrdə, məsələn おはよう-da görünən formadır.","en":"An い-adjective equivalent to いい; よう occurs in some expressions such as おはよう.","ru":"い-прилагательное, равнозначное いい; форма よう встречается в выражениях вроде おはよう."}},"よう":{"b":"よう","p":"an","m":{"az":"kimi, sanki","en":"like, as if","ru":"подобно, словно"},"n":{"az":"Bənzətmə bildirir: Nのような isimdən əvvəl, Nのように feldən əvvəl, Nのようです isə cümlənin sonunda işlənir.","en":"Expresses resemblance: Nのような modifies a noun, Nのように modifies a verb, and Nのようです ends a sentence.","ru":"Выражает сходство: Nのような стоит перед существительным, Nのように перед глаголом, а Nのようです завершает предложение."}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ケンタ":{"b":"ケンタ","p":"nm","m":{"az":"Kenta","en":"Kenta","ru":"Кэнта"}},"ソラ":{"b":"ソラ","p":"nm","m":{"az":"Sora","en":"Sora","ru":"Сора"}},"ダンス":{"b":"ダンス","p":"n","m":{"az":"rəqs","en":"dance; dancing","ru":"танец; танцы"},"n":{"az":"ダンスをする = rəqs etmək.","en":"ダンスをする means to dance.","ru":"ダンスをする означает танцевать."}},"バス":{"b":"バス","p":"n","m":{"az":"avtobus","en":"bus","ru":"автобус"}},"ポケット":{"b":"ポケット","p":"n","m":{"az":"cib","en":"pocket","ru":"карман"}},"ユイ":{"b":"ユイ","p":"nm","m":{"az":"Yui","en":"Yui","ru":"Юи"}},"ユイさん":{"b":"ユイ (ゆい)","p":"nm","m":{"az":"Yui","en":"Yui","ru":"Юи"},"n":{"az":"さん ada əlavə olunan hörmət şəkilçisidir.","en":"さん is a polite suffix added to a name.","ru":"さん является вежливым суффиксом после имени."}},"一つ":{"b":"一つ (ひとつ)","p":"n","m":{"az":"bir (dənə)","en":"one (thing)","ru":"одна (штука)"},"n":{"az":"Ümumi sayğac: 一つ, 二つ, 三つ.","en":"General counter: 一つ, 二つ, 三つ.","ru":"Общий счёт: 一つ, 二つ, 三つ."}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一時間":{"b":"一時間 (いちじかん)","p":"ex","m":{"az":"bir saat","en":"one hour","ru":"один час"},"n":{"az":"時間 müddət bildirir: 一時間 = bir saat, 一時 = saat bir.","en":"時間 expresses duration: 一時間 = one hour, 一時 = one o'clock.","ru":"時間 обозначает длительность: 一時間 = один час, 一時 = час дня."}},"一番":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən; hamıdan çox","en":"most; best","ru":"самый; больше всего"},"n":{"az":"Sifətdən əvvəl üstünlük bildirir: 一番大きい = ən böyük; isim kimi «birinci yer» deməkdir.","en":"Before an adjective it marks the superlative: 一番大きい = biggest; as a noun it means first place.","ru":"Перед прилагательным выражает превосходную степень: 一番大きい = самый большой; как существительное означает первое место."}},"一緒":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlik, bir yerdə olma","en":"being together","ru":"совместность, пребывание вместе"},"n":{"az":"一緒に “birlikdə” deməkdir: 友達と一緒に “dostla birlikdə”.","en":"一緒に means “together,” as in 友達と一緒に “together with a friend.”","ru":"一緒に означает «вместе»: 友達と一緒に «вместе с другом»."}},"七十歳":{"b":"七十歳 (ななじゅっさい)","p":"nu","m":{"az":"yetmiş yaş","en":"seventy years old","ru":"семьдесят лет"},"n":{"az":"歳 yaş sayğacıdır; 十歳 hissəsi じゅっさい və ya じっさい oxunur.","en":"歳 counts age; 十歳 is read じゅっさい or じっさい.","ru":"歳 обозначает возраст; 十歳 читается じゅっさい или じっさい."}},"三人":{"b":"三人 (さんにん)","p":"nu","m":{"az":"üç nəfər","en":"three people","ru":"три человека"},"n":{"az":"人 insan sayğacıdır: 一人 hitori, 二人 futari, 三人 sannin.","en":"人 counts people: 一人 hitori, 二人 futari, 三人 sannin.","ru":"人 считает людей: 一人 hitori, 二人 futari, 三人 sannin."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"不思議":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli; qəribə","en":"mysterious; curious","ru":"загадочный; удивительный"},"n":{"az":"な-sifətidir: 不思議な話; isim kimi «sirr, möcüzə» də bildirir.","en":"A な-adjective: 不思議な話; as a noun it can mean a mystery or wonder.","ru":"な-прилагательное: 不思議な話; как существительное может означать тайну или чудо."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"二回":{"b":"二回 (にかい)","p":"n","m":{"az":"iki dəfə","en":"twice","ru":"два раза"},"n":{"az":"回 hərəkətin neçə dəfə edildiyini bildirir.","en":"回 counts occurrences of an action.","ru":"回 считает количество повторений действия."}},"五":{"b":"五 (ご)","p":"nu","m":{"az":"beş","en":"five","ru":"пять"}},"五人":{"b":"五人 (ごにん)","p":"nu","m":{"az":"beş nəfər","en":"five people","ru":"пять человек"},"n":{"az":"人 insan sayğacıdır və burada にん oxunur.","en":"人 counts people and is read にん here.","ru":"人 является счётным словом для людей и здесь читается にん."}},"今年":{"b":"今年 (ことし)","p":"n","m":{"az":"bu il","en":"this year","ru":"в этом году"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 今年行きます.","en":"Usually takes no に as a time expression: 今年行きます.","ru":"При обозначении времени обычно употребляется без に: 今年行きます."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"先週":{"b":"先週 (せんしゅう)","p":"n","m":{"az":"keçən həftə","en":"last week","ru":"на прошлой неделе"},"n":{"az":"Vaxt bildirəndə に işlənmir: 先週来ました.","en":"Takes no に as a time expression: 先週来ました.","ru":"При обозначении времени употребляется без に: 先週来ました."}},"光":{"b":"光 (ひかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"六":{"b":"六 (ろく)","p":"nu","m":{"az":"altı","en":"six","ru":"шесть"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"切符":{"b":"切符 (きっぷ)","p":"n","m":{"az":"bilet","en":"ticket","ru":"билет"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"動かす":{"b":"動かす (うごかす)","p":"v","m":{"az":"hərəkət etdirmək; tərpətmək","en":"to move something","ru":"двигать; перемещать"},"n":{"az":"Təsirlidir: 机を動かす; təsirsiz qarşılığı 動く-dur.","en":"Transitive: 机を動かす; its intransitive partner is 動く.","ru":"Переходный: 机を動かす; непереходная пара: 動く."}},"十":{"b":"十 (じゅう)","p":"nu","m":{"az":"on","en":"ten","ru":"десять"}},"去年":{"b":"去年 (きょねん)","p":"n","m":{"az":"keçən il","en":"last year","ru":"в прошлом году"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 去年行きました.","en":"Usually takes no に as a time expression: 去年行きました.","ru":"При обозначении времени обычно употребляется без に: 去年行きました."}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"名前":{"b":"名前 (なまえ)","p":"n","m":{"az":"ad","en":"name","ru":"имя"}},"向こう":{"b":"向こう (むこう)","p":"n","m":{"az":"o tərəf, qarşı tərəf","en":"over there, the other side","ru":"там, противоположная сторона"}},"土曜":{"b":"土曜 (どよう)","p":"n","m":{"az":"şənbə","en":"Saturday","ru":"суббота"},"n":{"az":"土曜日 sözünün qısa formasıdır.","en":"Short for 土曜日.","ru":"Сокращение от 土曜日."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"外":{"b":"外 (そと)","p":"n","m":{"az":"çöl, bayır","en":"outside","ru":"снаружи"},"n":{"az":"N の 外 = N-in çölü: 窓の外 = pəncərənin arxası (çöldə).","en":"N の 外 = outside N.","ru":"N の 外 = снаружи N."}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"奥":{"b":"奥 (おく)","p":"n","m":{"az":"içəri tərəf; dərinlik","en":"inner part; back","ru":"глубина; дальняя часть"},"n":{"az":"Yerə görə otağın içəri tərəfini, mağazanın arxasını və ya meşənin dərinliyini bildirir.","en":"Depending on the place, it means the inner part of a room, the back of a shop, or deep inside a forest.","ru":"В зависимости от места обозначает глубину комнаты, дальнюю часть магазина или глубь леса."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"学生":{"b":"学生 (がくせい)","p":"n","m":{"az":"tələbə","en":"student","ru":"студент"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"家族":{"b":"家族 (かぞく)","p":"n","m":{"az":"ailə","en":"family","ru":"семья"}},"小さい":{"b":"小さい (ちいさい)","p":"ai","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"i-sifət; isimdən əvvəl olduğu kimi gəlir: 小さい子 = balaca uşaq.","en":"i-adjective; goes straight before a noun: 小さい子 = a little child.","ru":"i-прилагательное; ставится прямо перед существительным."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"島":{"b":"島 (しま)","p":"n","m":{"az":"ada","en":"island","ru":"остров"}},"席":{"b":"席 (せき)","p":"n","m":{"az":"yer; oturacaq yeri","en":"seat; place","ru":"место"},"n":{"az":"Nəqliyyatda, sinifdə və ya masada bir şəxsin yerini bildirə bilər.","en":"Can mean someone's place on transport, in class, or at a table.","ru":"Может обозначать чьё-либо место в транспорте, классе или за столом."}},"帰り":{"b":"帰り (かえり)","p":"n","m":{"az":"qayıdış; geri yol","en":"return; way back","ru":"возвращение; обратный путь"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"帽子":{"b":"帽子 (ぼうし)","p":"n","m":{"az":"papaq; şlyapa","en":"hat; cap","ru":"шляпа; шапка"}},"座席":{"b":"座席 (ざせき)","p":"n","m":{"az":"oturacaq","en":"seat","ru":"сиденье; посадочное место"}},"廊下":{"b":"廊下 (ろうか)","p":"n","m":{"az":"dəhliz","en":"corridor, hallway","ru":"коридор"}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"旅行":{"b":"旅行 (りょこう)","p":"n","m":{"az":"səyahət","en":"travel; trip","ru":"путешествие; поездка"},"n":{"az":"旅行する = səyahət etmək; 旅行に行く = səyahətə getmək.","en":"旅行する means to travel; 旅行に行く means to go on a trip.","ru":"旅行する означает путешествовать; 旅行に行く означает отправляться в поездку."}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"明かり":{"b":"明かり (あかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"星":{"b":"星 (ほし)","p":"n","m":{"az":"ulduz","en":"star","ru":"звезда"}},"星たち":{"b":"星 (ほし)","p":"n","m":{"az":"ulduzlar","en":"stars","ru":"звёзды"},"n":{"az":"たち burada ulduzları bir qrup kimi təqdim edir və onlara canlılıq verir.","en":"たち groups the stars and gives them a personified feel here.","ru":"たち здесь объединяет звёзды в группу и придаёт им черты живых существ."}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"昼":{"b":"昼 (ひる)","p":"n","m":{"az":"günorta; gündüz","en":"noon; daytime","ru":"полдень; дневное время"}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"月":{"b":"月 (つき)","p":"n","m":{"az":"Ay","en":"the Moon","ru":"Луна"},"n":{"az":"Təqvim ayı mənasında がつ/げつ oxunur.","en":"As 'month' it is read がつ/げつ.","ru":"В значении 'месяц' читается がつ/げつ."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"朝ご飯":{"b":"朝ご飯 (あさごはん)","p":"n","m":{"az":"səhər yeməyi","en":"breakfast","ru":"завтрак"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"来週":{"b":"来週 (らいしゅう)","p":"n","m":{"az":"gələn həftə","en":"next week","ru":"на следующей неделе"},"n":{"az":"Vaxt bildirəndə に işlənmir: 来週行きます.","en":"Takes no に as a time expression: 来週行きます.","ru":"При обозначении времени употребляется без に: 来週行きます."}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"横":{"b":"横 (よこ)","p":"n","m":{"az":"yan; böyür","en":"side; beside","ru":"бок; рядом"},"n":{"az":"Nの横 = N-in yanı; üfüqi istiqamət mənası da var.","en":"Nの横 means beside N; 横 can also refer to a horizontal direction.","ru":"Nの横 означает рядом с N; 横 также обозначает горизонтальное направление."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歌":{"b":"歌 (うた)","p":"n","m":{"az":"mahnı","en":"song","ru":"песня"}},"歌う":{"b":"歌う (うたう)","p":"v","m":{"az":"oxumaq; mahnı oxumaq","en":"to sing","ru":"петь"},"n":{"az":"歌を歌う = mahnı oxumaq; て-forması 歌って-dir.","en":"歌を歌う means to sing a song; its て-form is 歌って.","ru":"歌を歌う означает петь песню; て-форма: 歌って."}},"歌声":{"b":"歌声 (うたごえ)","p":"n","m":{"az":"oxuma səsi; mahnı səsi","en":"singing voice","ru":"певческий голос; пение"}},"止まる":{"b":"止まる (とまる)","p":"v","m":{"az":"dayanmaq","en":"to stop","ru":"останавливаться"},"n":{"az":"Təsirsizdir: バスが止まる; təsirli qarşılığı 止める-dir.","en":"Intransitive: バスが止まる; its transitive partner is 止める.","ru":"Непереходный: バスが止まる; переходная пара: 止める."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"母":{"b":"母 (はは)","p":"n","m":{"az":"ana","en":"mother","ru":"мать"},"n":{"az":"Başqaları ilə danışarkən öz ananı bildirmək üçün işlənir; anaya müraciətdə adətən お母さん deyilir.","en":"Used for one's own mother when speaking to others; お母さん is usual when addressing her.","ru":"Употребляется о своей матери в разговоре с другими; при обращении к ней обычно используется お母さん."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"流れる":{"b":"流れる (ながれる)","p":"v","m":{"az":"axmaq; yayılmaq","en":"to flow; to drift","ru":"течь; разноситься"},"n":{"az":"Təsirsizdir, təsirli qarşılığı 流す-dur; 音楽が流れる musiqinin səslənməsini bildirir.","en":"Intransitive, paired with 流す; 音楽が流れる means music is playing.","ru":"Непереходный, пара: 流す; 音楽が流れる означает, что звучит музыка."}},"海":{"b":"海 (うみ)","p":"n","m":{"az":"dəniz","en":"sea","ru":"море"}},"温かい":{"b":"温かい (あたたかい)","p":"ai","m":{"az":"isti; ilıq; mehriban","en":"warm; kind","ru":"тёплый; душевный"},"n":{"az":"い-sifətidir; əşya və münasibətlər üçün 温かい, hava üçün adətən 暖かい yazılır.","en":"An い-adjective; 温かい is used for objects and kindness, while weather usually takes 暖かい.","ru":"い-прилагательное; 温かい относится к предметам и душевной теплоте, а для погоды обычно пишут 暖かい."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"白い":{"b":"白い (しろい)","p":"ai","m":{"az":"ağ","en":"white","ru":"белый"}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"秘密":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr","en":"secret","ru":"секрет; тайна"}},"穴":{"b":"穴 (あな)","p":"n","m":{"az":"deşik; çuxur","en":"hole; pit","ru":"отверстие; яма"}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"窓":{"b":"窓 (まど)","p":"n","m":{"az":"pəncərə","en":"window","ru":"окно"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答え":{"b":"答え (こたえ)","p":"n","m":{"az":"cavab","en":"answer","ru":"ответ"}},"箱":{"b":"箱 (はこ)","p":"n","m":{"az":"qutu","en":"box","ru":"коробка"}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"自転車":{"b":"自転車 (じてんしゃ)","p":"n","m":{"az":"velosiped","en":"bicycle","ru":"велосипед"}},"船":{"b":"船 (ふね)","p":"n","m":{"az":"gəmi, qayıq","en":"ship, boat","ru":"корабль, лодка"}},"落ちる":{"b":"落ちる (おちる)","p":"v","m":{"az":"düşmək, yıxılmaq","en":"to fall","ru":"падать"},"n":{"az":"落ちて来る = düşüb gəlmək (aşağı).","en":"落ちて来る = come falling down.","ru":"落ちて来る = упасть (сюда)."}},"行き先":{"b":"行き先 (いきさき)","p":"n","m":{"az":"gediləcək yer","en":"destination","ru":"место назначения"}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見える":{"b":"見える (みえる)","p":"v","m":{"az":"görünmək","en":"to be visible, to appear","ru":"быть видным"},"n":{"az":"道が見えました = yol göründü (が ilə).","en":"道が見えました = a path came into view.","ru":"道が見えました = показалась дорога."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"誕生":{"b":"誕生 (たんじょう)","p":"n","m":{"az":"doğulma, yaranma","en":"birth, creation","ru":"рождение, возникновение"},"n":{"az":"“Ad günü” üçün 誕生日 işlənir; 誕生する “doğulmaq, yaranmaq” deməkdir.","en":"“Birthday” is 誕生日; 誕生する means “be born” or “come into being.”","ru":"«День рождения» обозначается словом 誕生日; 誕生する означает «родиться, возникнуть»."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"踊る":{"b":"踊る (おどる)","p":"v","m":{"az":"rəqs etmək","en":"dance","ru":"танцевать"}},"転がる":{"b":"転がる (ころがる)","p":"v","m":{"az":"diyirlənmək","en":"to roll","ru":"катиться"},"n":{"az":"Özü diyirlənmək 転がる, nəyisə diyirlətmək 転がす ilə ifadə olunur.","en":"転がる means to roll by itself; 転がす means to roll something.","ru":"転がる означает катиться, а 転がす означает катить что-либо."}},"運転":{"b":"運転 (うんてん)","p":"n","m":{"az":"nəqliyyat vasitəsini idarə etmə","en":"driving","ru":"вождение"},"n":{"az":"運転する nəqliyyat vasitəsini idarə etmək deməkdir.","en":"運転する means to drive a vehicle.","ru":"運転する означает управлять транспортным средством."}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"金":{"b":"金 (かね／きん)","p":"n","m":{"az":"pul; qızıl","en":"money; gold","ru":"деньги; золото"},"n":{"az":"Pul mənasında かね, adətən お金, qızıl mənasında isə きん oxunur.","en":"Read かね for money, usually お金, and きん for gold.","ru":"В значении «деньги» читается かね, обычно お金, а в значении «золото» читается きん."}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"隣":{"b":"隣 (となり)","p":"n","m":{"az":"yan, qonşuluq","en":"next door, next to","ru":"соседство, рядом"},"n":{"az":"Nの隣 birbaşa N-in yanındakı yeri bildirir.","en":"Nの隣 refers to a place directly next to N.","ru":"Nの隣 обозначает место непосредственно рядом с N."}},"電話":{"b":"電話 (でんわ)","p":"n","m":{"az":"telefon; telefon zəngi","en":"telephone; phone call","ru":"телефон; звонок"},"n":{"az":"電話する və 電話をかける telefonla zəng etmək deməkdir.","en":"電話する and 電話をかける both mean to make a phone call.","ru":"電話する и 電話をかける означают звонить по телефону."}},"電車":{"b":"電車 (でんしゃ)","p":"n","m":{"az":"elektrik qatarı","en":"electric train","ru":"электропоезд"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"靴":{"b":"靴 (くつ)","p":"n","m":{"az":"ayaqqabı","en":"shoes","ru":"обувь, туфли"}},"音楽":{"b":"音楽 (おんがく)","p":"n","m":{"az":"musiqi","en":"music","ru":"музыка"}},"食べる":{"b":"食べる (たべる)","p":"v","m":{"az":"yemək","en":"to eat","ru":"есть"}},"首":{"b":"首 (くび)","p":"n","m":{"az":"boyun; baş","en":"neck; head","ru":"шея; голова"},"n":{"az":"首をふる = başını bulamaq (inkar).","en":"首をふる = shake one's head.","ru":"首をふる = покачать головой."}},"駅":{"b":"駅 (えき)","p":"n","m":{"az":"stansiya","en":"station","ru":"станция"}},"鳴る":{"b":"鳴る (なる)","p":"v","m":{"az":"çalmaq, səslənmək","en":"ring, sound","ru":"звенеть, звучать"},"n":{"az":"Keçişsiz feldir: ベルが鳴る “zəng çalır”; keçişli qarşılığı 鳴らす “səsləndirmək” sözüdür.","en":"An intransitive verb: ベルが鳴る “the bell rings”; its transitive counterpart is 鳴らす “make ring.”","ru":"Непереходный глагол: ベルが鳴る «звенит звонок»; переходная пара 鳴らす означает «заставлять звучать»."}},"黄色い":{"b":"黄色い (きいろい)","p":"ai","m":{"az":"sarı","en":"yellow","ru":"жёлтый"},"n":{"az":"İ-sifətdir; rəngin isim forması 黄色 olur.","en":"An i-adjective; the noun for the color is 黄色.","ru":"И-прилагательное; существительное для цвета: 黄色."}},"黒い":{"b":"黒い (くろい)","p":"ai","m":{"az":"qara","en":"black","ru":"чёрный"},"n":{"az":"İ-sifətdir; rəngin isim forması 黒 olur.","en":"An i-adjective; the noun for the color is 黒.","ru":"И-прилагательное; существительное для цвета: 黒."}}}};